                Fit.of(wideRow, 1024f),
                Fit.of(compactRow))
                .modifiers(
                        frame(f -> f.width(Commands.Size.FILL).height(Commands.Size.FILL)),
                        accessibilityRole(Roles.MAIN));
    }

